const BASE={AAPL:23400,MSFT:42600,GOOGL:18200,AMZN:19500,NVDA:12800,META:52000,TSLA:24800,AMD:16400,KO:6300,JNJ:15600,PG:16900,XOM:11400,CVX:15800,SPY:56000,QQQ:49000,VOO:51500,BTC:6800000,ETH:380000};
const DIV=new Set(['AAPL','MSFT','KO','JNJ','PG','XOM','CVX','VOO']);
const BY=Object.fromEntries(ASSETS.map(a=>[a.symbol,a]));
const HOUR=3600000;
function hsym(s){let h=0x811c9dc5;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,0x01000193);}return h>>>0;}
function r01(seed){let t=(seed+0x6d2b79f5)>>>0;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;}
function noiseAt(sd,n){return r01(sd+Math.imul(n>>>0,0x9e3779b1))*2-1;}
function sn(sd,x){const i=Math.floor(x),f=x-i,u=f*f*(3-2*f);return noiseAt(sd,i)*(1-u)+noiseAt(sd,i+1)*u;}
function ln(sd,x){let s=0,a=1,f=1,n=0;for(let o=0;o<4;o++){s+=sn(sd+o*1013,x*f)*a;n+=a;a*=0.5;f*=2.13;}return s/n;}
function amp(sym){const a=BY[sym];if(a&&a.type==='crypto')return 0.28;if(a&&a.type==='etf')return 0.06;return 0.12;}
function bp(sym){return BASE[sym]!=null?BASE[sym]:10000;}
function priceAt(sym,t){const sd=hsym(sym),x=t/HOUR/24,d=ln(sd,x);return Math.max(1,Math.round(bp(sym)*(1+amp(sym)*d)));}
const DAYI={Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6};
function nyParts(now){try{const f=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false});const p={};for(const x of f.formatToParts(new Date(now)))p[x.type]=x.value;const day=DAYI[p.weekday],h=Number(p.hour)%24,mi=Number(p.minute);if(day===undefined||!Number.isFinite(h)||!Number.isFinite(mi))return null;return{day,mins:h*60+mi};}catch(e){return null;}}
function nthSunUtc(y,m,n){const f=new Date(Date.UTC(y,m,1)),sh=(7-f.getUTCDay())%7;return new Date(Date.UTC(y,m,1+sh+(n-1)*7,7));}
function usDst(d){const y=d.getUTCFullYear();return d>=nthSunUtc(y,2,2)&&d<nthSunUtc(y,10,1);}
// Сессия считается по Нью-Йорку (09:30-16:00), а не зашитым UTC-минутам:
// иначе зимой индикатор «рынок открыт» врёт на час.
function mktOpen(sym,now){const a=BY[sym];if(a&&a.type==='crypto')return true;const ny=nyParts(now);if(ny){if(ny.day===0||ny.day===6)return false;return ny.mins>=570&&ny.mins<960;}const d=new Date(now),day=d.getUTCDay();if(day===0||day===6)return false;const open=(usDst(d)?13:14)*60+30,m=d.getUTCHours()*60+d.getUTCMinutes();return m>=open&&m<open+390;}
