const RP={'1d':{count:24,step:HOUR},'1w':{count:28,step:6*HOUR},'1m':{count:30,step:24*HOUR},'1y':{count:52,step:7*24*HOUR}};
function candlesFor(sym,range,now){const p=RP[String(range||'').toLowerCase()]||RP['1d'],sd=hsym(sym),out=[];for(let i=p.count-1;i>=0;i--){const tc=now-i*p.step,to=tc-p.step,c=priceAt(sym,tc),o=priceAt(sym,to),b=Math.floor(tc/p.step),wu=Math.abs(noiseAt(sd+7,b))*0.006,wd=Math.abs(noiseAt(sd+13,b))*0.006,hi=Math.round(Math.max(o,c)*(1+wu)),lo=Math.round(Math.min(o,c)*(1-wd));out.push({t:tc,o,h:Math.max(hi,o,c),l:Math.min(lo,o,c),c});}return out;}
// Якорный дивидендный календарь. Было: ex-date = now + 5..40 дней, и дата
// пересчитывалась при КАЖДОМ запросе, поэтому отсечка вечно убегала вперёд,
