const QDAYS=91;
function dividendsFor(sym,now){if(!DIV.has(sym))return[];const sd=hsym(sym),off=Math.floor(r01(sd+101)*QDAYS),step=QDAYS*24*HOUR,anchor=DIV_EPOCH+off*24*HOUR,k=Math.floor((now-anchor)/step),per=Math.max(1,Math.round(bp(sym)*0.004*(0.6+r01(sd+202)))),mk=(i)=>{const ex=new Date(anchor+i*step),pay=new Date(ex.getTime()+7*24*HOUR);return{symbol:sym,exDate:ex.toISOString().slice(0,10),payDate:pay.toISOString().slice(0,10),perShareCents:per};},out=[];if(k>=0)out.push(mk(k));out.push(mk(k+1));return out;}
const now=Date.now();
return [{json:{ok:true,ai:true,market:'synthetic'}}];

